python -c "
import numpy as np; W=dict(np.load('weights.npz'))
np.set_printoptions(precision=2,suppress=True,linewidth=200)
for l in range(4):
  w1=W[f'ln1_w.{l}'];w2=W[f'ln2_w.{l}']
  print(l,'ln1w',np.percentile(w1,[0,5,50,95,100]),'ln2w',np.percentile(w2,[0,5,50,95,100]))
  M=np.vstack([W[f'W_q.{l}']*w1,W[f'W_k.{l}']*w1,W[f'W_v.{l}']*w1])
  s=np.linalg.svd(M,compute_uv=False); print(' attn in sv',s[:40:2]); 
  s=np.linalg.svd(W[f'W_fc.{l}']*w2,compute_uv=False); print(' fc sv',s[:40:2])
"

